insert into public.exam_questions(id,session_id,variant,section,question_no,official_url,pdf_start_page,pdf_page,crop,classification,width,height)
select id,sid,variant,section,n,d->>'official_url',1,page,d->'crop',d->'classification',(d->>'width')::int,(d->>'height')::int
from historical_questions on conflict(id) do nothing;
alter table public.problems disable trigger problems_rate;
alter table public.problems disable trigger problems_reward;
insert into public.problems(id,owner_id,exam_question_id,title,question,grade,subject,unit,curriculum_id,source,source_details,public,rights_confirmed)
select id,null,id,title,'공식 기출 수학 문제입니다.',grade,subject,'미분류','2015',source,d,true,true
from historical_questions on conflict(id) do nothing;
alter table public.problems enable trigger problems_rate;
alter table public.problems enable trigger problems_reward;
insert into public.problem_difficulties(problem_id,level,classification_method,correct_rate,rate_basis,source_url,source_exam_seq,rate_collected_at,rule_version)
select id,level,'correct_rate',rate,basis,url,seq,collected,'megastudy-20-50-80-v1' from historical_questions where rate is not null
on conflict(problem_id) do nothing;

do $$begin
 if (select count(*) from historical_questions h
  join public.exam_questions q on q.id=h.id and q.session_id=h.sid and q.section=h.section and q.variant=h.variant
   and q.question_no=h.n and q.pdf_page=h.page and q.official_url=h.d->>'official_url' and q.crop=h.d->'crop'
  join public.problems p on p.exam_question_id=q.id and p.public and p.source_details=h.d) <> 1328
 then raise exception 'Historical questions are missing or inconsistent'; end if;
 if exists(select 1 from historical_questions q where q.rate is not null and not exists(
   select 1 from public.problem_difficulties d where d.problem_id=q.id and
    (d.classification_method='manual' or (d.correct_rate=q.rate and d.level=q.level and d.rate_basis=q.basis))))
 then raise exception 'Historical difficulty data is inconsistent'; end if;
end$$;
commit;
